"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[1783],{24986(e){e.exports=JSON.parse('{"tag":{"label":"3-sat","permalink":"/azeon/p-vs-np/tags/3-sat","allTagsPath":"/azeon/p-vs-np/tags","count":6,"items":[{"id":"np-completeness/14-3-sat-the-building-block","title":"3-SAT: The Building Block","description":"Why restricting every clause to exactly three literals keeps SAT just as hard, and how the reduction from SAT to 3-SAT actually works step by step.","permalink":"/azeon/p-vs-np/np-completeness/3-sat-the-building-block"},{"id":"np-completeness/graph-coloring","title":"Graph Coloring","description":"A map, a box of crayons, and the strangest jump in this whole series: with two colours the problem is easy, with three it is NP-Complete. Here is why one extra colour changes everything.","permalink":"/azeon/p-vs-np/np-completeness/graph-coloring"},{"id":"np-completeness/hamiltonian-cycle","title":"Hamiltonian Cycle","description":"Visit every city exactly once and come home. It started as a Victorian puzzle game, and it has a twin about roads instead of cities that is easy. Why one is easy and the other is NP-Complete is the real lesson.","permalink":"/azeon/p-vs-np/np-completeness/hamiltonian-cycle"},{"id":"np-completeness/subset-sum","title":"Subset Sum","description":"Can some of these numbers add up to exactly the target? I finally prove it\'s NP-Complete, by turning a logic formula into a list of carefully designed numbers where every digit is doing a job.","permalink":"/azeon/p-vs-np/np-completeness/subset-sum"},{"id":"np-completeness/the-clique-problem","title":"The Clique Problem","description":"What does finding mutual friends in a social network have to do with Boolean logic? The reduction from 3-SAT to Clique is the bridge, and it is one of the most satisfying constructions in all of NP-Completeness.","permalink":"/azeon/p-vs-np/np-completeness/the-clique-problem"},{"id":"np-completeness/independent-set","title":"The Independent Set Problem","description":"I have used Independent Set as a stepping stone twice without ever proving it is hard. Today I pay that debt, once the lazy way and once the honest way, straight from 3-SAT.","permalink":"/azeon/p-vs-np/np-completeness/independent-set"}],"unlisted":false}}')}}]);